import{_ as o,o as t,c as r,a2 as s}from"./chunks/framework.CHeM0PsO.js";const g=JSON.parse('{"title":"Sovereign repositories","description":"","frontmatter":{"docSection":"architecture-security","docType":"reference","audiences":["operator","app-developer","contributor"]},"headers":[],"relativePath":"repositories.md","filePath":"repositories.md"}'),i={name:"repositories.md"};function a(n,e,d,c,l,p){return t(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="sovereign-repositories" tabindex="-1">Sovereign repositories <a class="header-anchor" href="#sovereign-repositories" aria-label="Permalink to &quot;Sovereign repositories&quot;">​</a></h1><p>Sovereign uses a small set of first-party repositories. This page is the canonical map for what each repository owns, whether it is active or archived, and which docs should point to it.</p><h2 id="core-repositories" tabindex="-1">Core repositories <a class="header-anchor" href="#core-repositories" aria-label="Permalink to &quot;Core repositories&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Repository</th><th>Status</th><th>Purpose</th></tr></thead><tbody><tr><td><a href="https://github.com/sovereignfs/sovereign" target="_blank" rel="noreferrer"><code>sovereignfs/sovereign</code></a></td><td>Active</td><td>Primary platform repository: runtime, auth app, packages, built-in platform plugins, docs, RFCs, and roadmap.</td></tr><tr><td><a href="https://github.com/sovereignfs/sovereign-legacy" target="_blank" rel="noreferrer"><code>sovereignfs/sovereign-legacy</code></a></td><td>Archived</td><td>Previous Sovereign codebase. Kept for historical reference and migration context only; new work happens in <code>sovereignfs/sovereign</code>.</td></tr></tbody></table><h2 id="client-shell-repositories" tabindex="-1">Client shell repositories <a class="header-anchor" href="#client-shell-repositories" aria-label="Permalink to &quot;Client shell repositories&quot;">​</a></h2><p>Native client shells that load a user&#39;s self-hosted instance in a WebView. They own only shell concerns — instance-URL onboarding, persistent instance storage, WebView lifecycle, native permission declarations, store metadata. Auth, plugins, shell layout, and CSP always come from the user&#39;s own instance. See <a href="./../CLAUDE.html">CLAUDE.md</a> (&quot;Native mobile app&quot; / &quot;Desktop app&quot;), <a href="./rfcs/0058-native-mobile-app-shell.html">RFC 0058</a>, and <a href="./rfcs/0038-desktop-app-shell.html">RFC 0038</a>.</p><table tabindex="0"><thead><tr><th>Repository</th><th>Status</th><th>Purpose</th></tr></thead><tbody><tr><td><a href="https://github.com/sovereignfs/sovereign-desktop" target="_blank" rel="noreferrer"><code>sovereignfs/sovereign-desktop</code></a></td><td>Active</td><td>Tauri 2.x desktop shell — macOS first, Windows and Linux from the same codebase. Distributed via GitHub Releases (<code>.dmg</code>, <code>.exe</code>/<code>.msi</code>, <code>.AppImage</code>/<code>.deb</code>). Epic 17.</td></tr><tr><td><a href="https://github.com/sovereignfs/sovereign-mobile" target="_blank" rel="noreferrer"><code>sovereignfs/sovereign-mobile</code></a></td><td>Not yet created</td><td>Capacitor shell for iOS and Android, published to the App Store and Play Store, plus a device-bridge layer (RFC 0083) for <code>sdk.device.*</code>. Code created by epic task 20.1; tracked as <a href="./workstreams/0002-native-mobile-app-release.html">workstream 0002</a>. Planning docs (<code>CONCEPT.md</code>, <code>ROADMAP.md</code>, <code>AGENTS.md</code>, ADRs) already exist in the local checkout as of 2026-07-31, ahead of the GitHub repo and any code.</td></tr></tbody></table><h2 id="plugin-repositories" tabindex="-1">Plugin repositories <a class="header-anchor" href="#plugin-repositories" aria-label="Permalink to &quot;Plugin repositories&quot;">​</a></h2><p>Individual product plugin repositories (Tasks, Plainwrite, and any other first-party or community plugin) are tracked in the plugin registry (<code>registry/plugins.json</code>), not in a table on this page — see <a href="./../registry/CONTRIBUTING.html"><code>registry/CONTRIBUTING.md</code></a> for the submission process. The one exception is <a href="https://github.com/sovereignfs/sovereign-plugin-template" target="_blank" rel="noreferrer"><code>sovereignfs/sovereign-plugin-template</code></a>, the canonical standalone plugin starter repository — it isn&#39;t itself an installable plugin, so it has no registry entry.</p><p><code>sovereignfs/sovereign-plugins-examples</code> has been retired: the example plugins it previously hosted now live in-repo under <code>example-plugins/</code> (see <code>docs/adhoc/example-plugins-plan.md</code>).</p><h2 id="documentation-and-deployment-support" tabindex="-1">Documentation and deployment support <a class="header-anchor" href="#documentation-and-deployment-support" aria-label="Permalink to &quot;Documentation and deployment support&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Repository</th><th>Status</th><th>Purpose</th></tr></thead><tbody><tr><td><a href="https://github.com/sovereignfs/storybook" target="_blank" rel="noreferrer"><code>sovereignfs/storybook</code></a></td><td>Active deployment target</td><td>GitHub Pages repository for the built <code>@sovereignfs/ui</code> Storybook static site, served at <a href="https://sovereignfs.github.io/storybook/" target="_blank" rel="noreferrer"><code>sovereignfs.github.io/storybook</code></a>. Source stories live in this primary repository under <code>packages/ui</code>.</td></tr><tr><td><a href="https://github.com/sovereignfs/sovereign-infra" target="_blank" rel="noreferrer"><code>sovereignfs/sovereign-infra</code></a></td><td>Active template</td><td>Operator-owned self-hosting template for Ubuntu VPS deployments: Caddy, Docker Compose, age-encrypted <code>.env</code> files, matching-tag deploys of official Sovereign images, and GitHub Actions CI/CD. No Terraform or managed-cloud dependency.</td></tr><tr><td><a href="https://github.com/sovereignfs/sovereignfs" target="_blank" rel="noreferrer"><code>sovereignfs/sovereignfs</code></a></td><td>Active</td><td>The ecosystem workbench repo. Builds and deploys the public VitePress docs site (<code>docs/</code> there) by fetching allowlisted content from this repository&#39;s <code>docs/</code> (and <code>sovereign-os</code>&#39;s) at build time via <code>docs/docs-sync.manifest.json</code> — this repository holds the source prose, but no docs-site code.</td></tr><tr><td><a href="https://github.com/sovereignfs/sovereignfs.github.io" target="_blank" rel="noreferrer"><code>sovereignfs/sovereignfs.github.io</code></a></td><td>Active deployment target</td><td>GitHub Pages repository for the public docs site at <a href="https://sovereignfs.github.io/" target="_blank" rel="noreferrer"><code>sovereignfs.github.io</code></a>, published from <code>sovereignfs/sovereignfs</code>. Source prose lives in this primary repository under <code>docs/</code>; the VitePress app and build config live in <code>sovereignfs/sovereignfs</code>, not here.</td></tr></tbody></table><h2 id="naming-notes" tabindex="-1">Naming notes <a class="header-anchor" href="#naming-notes" aria-label="Permalink to &quot;Naming notes&quot;">​</a></h2><ul><li>Product plugin repositories follow <code>sovereignfs/sovereign-plugin-&lt;name&gt;</code> (e.g. <code>sovereign-plugin-tasks</code>, <code>sovereign-plugin-plainwrite</code>) — the <code>plugin-</code> segment distinguishes an installable plugin repo from platform and client-shell repos at a glance. This does not affect a plugin&#39;s own <code>package.json</code> name or manifest <code>id</code>, which are unrelated to its repo name.</li><li><code>sovereignfs/storybook</code> and <code>sovereignfs/sovereignfs.github.io</code> are deployment targets. Edit source stories and docs in <code>sovereignfs/sovereign</code>.</li><li><code>sovereignfs/sovereign-infra</code> is a template that operators fork or use as a GitHub template. The platform repository publishes release images; the operator&#39;s infra repository controls when those images are deployed to the operator&#39;s VPS.</li><li>Historical planning docs may mention older candidate repositories such as Splitify, API Composer, or PaperTrail. They are not part of the current support-repository set unless this page is updated.</li></ul>',14)])])}const u=o(i,[["render",a]]);export{g as __pageData,u as default};
